/**
 * Generated by `createservice subscription.ActivateSubscriptionContextService --type mutations`
 */

const { getLogger } = require('@open-condo/keystone/logging')
const { GQLCustomSchema } = require('@open-condo/keystone/schema')

const access = require('@condo/domains/subscription/access/ActivateSubscriptionContextService')
const { ACTIVATE_SUBSCRIPTION_CONTEXT_ERRORS: ERRORS } = require('@condo/domains/subscription/constants/activateSubscriptionContextErrors')
const {
    loadActivatableSubscriptionContextOrThrow,
    loadPaidInvoiceOrThrow,
    resolvePaymentInfo,
    activatePaidSubscriptionContext,
} = require('@condo/domains/subscription/utils/serverSchema/activateSubscriptionContext')

const logger = getLogger('ActivateSubscriptionContextService')

const ActivateSubscriptionContextService = new GQLCustomSchema('ActivateSubscriptionContextService', {
    types: [
        {
            access: true,
            type: 'input ActivateSubscriptionContextInput { dv: Int!, sender: SenderFieldInput!, subscriptionContext: SubscriptionContextWhereUniqueInput! }',
        },
        {
            access: true,
            type: 'type ActivateSubscriptionContextOutput { subscriptionContext: SubscriptionContext }',
        },
    ],

    mutations: [
        {
            access: access.canActivateSubscriptionContext,
            schema: 'activateSubscriptionContext(data: ActivateSubscriptionContextInput!): ActivateSubscriptionContextOutput',
            doc: {
                summary: 'Activates a subscription context whose invoice is paid: resolves the payment method (if any), sets status to DONE and recomputes startAt/endAt so the paid period starts at payment time rather than registration time.',
                errors: ERRORS,
            },
            resolver: async (parent, args, context) => {
                const { data } = args
                const { dv, sender, subscriptionContext: subscriptionContextInput } = data

                logger.info({ msg: 'Starting subscription context activation', data: { subscriptionContextId: subscriptionContextInput.id } })

                const subscriptionContext = await loadActivatableSubscriptionContextOrThrow(context, subscriptionContextInput.id)
                const invoice = await loadPaidInvoiceOrThrow(context, subscriptionContext)

                const { bindingId, paymentMethod, frozenPaymentInfo } = await resolvePaymentInfo(context, { invoice, subscriptionContext })

                const activatedSubscriptionContext = await activatePaidSubscriptionContext(context, {
                    subscriptionContext,
                    bindingId,
                    paymentMethod,
                    frozenPaymentInfo,
                    dv,
                    sender,
                })

                return { subscriptionContext: activatedSubscriptionContext }
            },
        },
    ],
})

module.exports = {
    ActivateSubscriptionContextService,
    ERRORS,
}
